import { App } from "@capacitor/app";
import { Capacitor } from "@capacitor/core";
import { LocalNotifications } from "@capacitor/local-notifications";
import { SecureStorage } from "@aparajita/capacitor-secure-storage-plugin";

const SESSION_KEY = "session";
const ALLOWED_HOSTS = new Set(["app.praxbit.test"]);

export interface Session {
    token: string;
    userId: string;
}

export interface SyncedOrder {
    id: string;
    revision: number;
    updatedAt: string;
    total: number;
}

export interface PlatformAdapter {
    saveSession(session: Session): Promise<void>;
    readSession(): Promise<Session | null>;
    clearSession(): Promise<void>;
    requestNotifications(): Promise<boolean>;
    onDeepLink(handler: (path: string) => void): Promise<void>;
}

export function createPlatformAdapter(): PlatformAdapter {
    const native = Capacitor.isNativePlatform();

    async function saveSession(session: Session): Promise<void> {
        if (native) {
            await SecureStorage.set(SESSION_KEY, JSON.stringify(session));
            return;
        }
        await fetch("/api/session", {
            method: "POST",
            headers: { "content-type": "application/json" },
            body: JSON.stringify({ token: session.token }),
        });
    }

    async function readSession(): Promise<Session | null> {
        if (!native) {
            return null;
        }
        const stored = await SecureStorage.get(SESSION_KEY);
        return stored ? (JSON.parse(stored) as Session) : null;
    }

    async function clearSession(): Promise<void> {
        if (native) {
            await SecureStorage.remove(SESSION_KEY);
        }
    }

    async function requestNotifications(): Promise<boolean> {
        const current = await LocalNotifications.checkPermissions();
        if (current.display === "granted") {
            return true;
        }
        const next = await LocalNotifications.requestPermissions();
        return next.display === "granted";
    }

    async function onDeepLink(handler: (path: string) => void): Promise<void> {
        if (!native) {
            return;
        }
        await App.addListener("appUrlOpen", async (event) => {
            const url = new URL(event.url);
            if (!ALLOWED_HOSTS.has(url.hostname)) {
                return;
            }
            const session = await readSession();
            if (!session) {
                return;
            }
            handler(url.pathname + url.search);
        });
    }

    return { saveSession, readSession, clearSession, requestNotifications, onDeepLink };
}

export function mergeOrder(local: SyncedOrder, server: SyncedOrder | null): SyncedOrder {
    if (server === null) {
        return local;
    }
    if (local.revision < server.revision) {
        return server;
    }
    if (local.revision === server.revision && local.updatedAt !== server.updatedAt) {
        throw new Error("Sync conflict: pull the newer server record first");
    }
    return local;
}
